package org.apache.commons.cli;

import org.junit.jupiter.api.Test;

import java.lang.reflect.Constructor;
import java.lang.reflect.Method;
import java.util.ArrayList;
import java.util.LinkedList;
import java.util.List;
import java.util.function.Consumer;

import static org.junit.jupiter.api.Assertions.*;

class CommandLine_getParsedOptionValuesTest {

    /**
     * A small test subclass that overrides the String-based variant so we can
     * observe what optionName is passed when calling the char-based focal method.
     * It simulates different return types for different option names.
     */
    static class TestableCommandLine extends CommandLine {
        String lastOptionName;

        @Override
        @SuppressWarnings("unchecked")
        public <T> T[] getParsedOptionValues(final String optionName, final T[] defaultValue) {
            this.lastOptionName = optionName;
            // simulated behavior depending on optionName
            if ("a".equals(optionName)) {
                // return a String[] when requested via char 'a'
                return (T[]) new String[]{"A:" + optionName};
            }
            if ("1".equals(optionName)) {
                // return an Integer[] when requested via char '1'
                return (T[]) new Integer[]{42};
            }
            if ("t".equals(optionName)) {
                // propagate a runtime exception to test propagation
                throw new RuntimeException("forced");
            }
            // otherwise return the provided default
            return defaultValue;
        }
    }

    @Test
    void shouldForwardCharToStringVariant_andReturnParsedStringArray() {
        TestableCommandLine cl = new TestableCommandLine();
        String[] defaultValue = new String[]{"def"};
        String[] result = cl.getParsedOptionValues('a', defaultValue);

        assertNotNull(result);
        assertEquals(1, result.length);
        assertEquals("A:a", result[0]);
        assertEquals("a", cl.lastOptionName, "The char should be converted to the same single-character String");
    }

    @Test
    void shouldReturnProvidedDefault_whenNoParsedValues() {
        TestableCommandLine cl = new TestableCommandLine();
        String[] defaultValue = new String[]{"def"};
        String[] result = cl.getParsedOptionValues('x', defaultValue);

        // when optionName not handled, the override returns the provided defaultValue reference
        assertSame(defaultValue, result);
        assertEquals("x", cl.lastOptionName);
    }

    @Test
    void shouldSupportGenericIntegerArray_returnedFromStringVariant() {
        TestableCommandLine cl = new TestableCommandLine();
        Integer[] defaultInts = new Integer[]{0};
        Integer[] result = cl.getParsedOptionValues('1', defaultInts);

        assertNotNull(result);
        assertArrayEquals(new Integer[]{42}, result);
        assertEquals("1", cl.lastOptionName);
    }

    @Test
    void shouldPropagateRuntimeExceptionFromStringVariant() {
        TestableCommandLine cl = new TestableCommandLine();
        // the override throws a RuntimeException when optionName == "t"
        assertThrows(RuntimeException.class, () -> cl.getParsedOptionValues('t', new String[]{}));
        assertEquals("t", cl.lastOptionName);
    }

    @Test
    void shouldInstantiateUsingPrivateConstructor_viaReflection() throws Exception {
        // Locate the private three-arg constructor (List, List, Consumer) and invoke it reflectively
        Constructor<CommandLine> ctor = CommandLine.class.getDeclaredConstructor(List.class, List.class, java.util.function.Consumer.class);
        ctor.setAccessible(true);

        List<String> args = new LinkedList<>();
        List<Object> options = new ArrayList<>(); // generics erased at runtime
        Consumer<Object> consumer = o -> {
        };

        CommandLine instance = ctor.newInstance(args, options, (Consumer) consumer);

        assertNotNull(instance);
        assertTrue(instance instanceof CommandLine);
    }

    @Test
    void shouldInvokeCharVariantReflectively() throws Exception {
        TestableCommandLine cl = new TestableCommandLine();
        // get the runtime method: parameters are (char, Object[]) because of type erasure
        Method m = CommandLine.class.getMethod("getParsedOptionValues", char.class, Object[].class);
        Object ret = m.invoke(cl, 'a', new Object[]{new String[]{"def"}});

        // ret is actually a String[]; verify its contents
        assertNotNull(ret);
        assertTrue(ret instanceof String[]);
        String[] result = (String[]) ret;
        assertEquals(1, result.length);
        assertEquals("A:a", result[0]);
        assertEquals("a", cl.lastOptionName);
    }
}

